// src/realmap.js — Real Kaduna map loader.
// Fetches /data/kaduna.json (generated by tools/osm-to-kaduna.mjs from OSM data),
// builds the real road network, river, and places Kenney houses on building
// footprints. Falls back to the procedural world if the data fails to load.
//
// © OpenStreetMap contributors (ODbL) — see CREDITS.md

import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";

const ROAD_COLORS = {
  primary: 0x4a4a4a,
  secondary: 0x555a60,
  tertiary: 0x6a6a6a,
  residential: 0x7a7a7a,
};

// Fetch the kaduna.json data. Returns null on failure.
export async function fetchKadunaData() {
  try {
    const res = await fetch("/data/kaduna.json");
    if (!res.ok) { console.warn("kaduna.json HTTP", res.status); return null; }
    const data = await res.json();
    if (!data.roads || !data.buildings) { console.warn("kaduna.json malformed"); return null; }
    console.log(`[realmap] Loaded ${data.roads.length} roads, ${data.buildings.length} buildings, ${data.landmarks?.length || 0} landmarks`);
    return data;
  } catch (e) {
    console.warn("[realmap] Could not load kaduna.json, falling back to procedural city:", e.message);
    return null;
  }
}

// Build the real Kaduna world into the given scene.
// Returns { group, colliders, mapShapes, dispose() } or null on failure.
export function buildRealMap(scene, data) {
  if (!data) return null;

  const group = new THREE.Group();
  group.name = "real_kaduna";
  const colliders = [];
  const mapShapes = { buildings: [], trees: [], sideStreets: [], crossings: [], stalls: [], roads: [] };

  // ---- Ground (grass) ----
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(800, 400),
    new THREE.MeshLambertMaterial({ color: 0x9aab62 })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  group.add(ground);

  // ---- Roads (merged by type — one draw call per road type) ----
  const roadGeosByType = { primary: [], secondary: [], tertiary: [], residential: [] };
  for (const road of data.roads) {
    const type = road.type in roadGeosByType ? road.type : "residential";
    const width = road.width || 8;
    const pts = road.points;
    for (let i = 0; i < pts.length - 1; i++) {
      const [x1, z1] = pts[i], [x2, z2] = pts[i + 1];
      const dx = x2 - x1, dz = z2 - z1;
      const len = Math.sqrt(dx * dx + dz * dz);
      if (len < 0.1) continue;
      const geo = new THREE.PlaneGeometry(width, len);
      // Position at midpoint, rotate to align with road direction
      geo.translate(0, 0, 0);
      geo.rotateX(-Math.PI / 2);
      geo.rotateY(-Math.atan2(dx, dz));
      geo.translate((x1 + x2) / 2, 0.02, (z1 + z2) / 2);
      roadGeosByType[type].push(geo);
    }
    // Add to mapShapes for minimap
    mapShapes.roads.push({ type, width, points: pts });
  }

  for (const [type, geos] of Object.entries(roadGeosByType)) {
    if (!geos.length) continue;
    const merged = mergeGeometries(geos);
    const mesh = new THREE.Mesh(merged, new THREE.MeshLambertMaterial({ color: ROAD_COLORS[type] }));
    mesh.receiveShadow = true;
    group.add(mesh);
    geos.forEach(g => g.dispose()); // free the pre-merge copies
  }

  // ---- Road markings (dashed center line on primary roads) ----
  const dashGeos = [];
  for (const road of data.roads) {
    if (road.type !== "primary") continue;
    const pts = road.points;
    for (let i = 0; i < pts.length - 1; i++) {
      const [x1, z1] = pts[i], [x2, z2] = pts[i + 1];
      const dx = x2 - x1, dz = z2 - z1;
      const len = Math.sqrt(dx * dx + dz * dz);
      const dashLen = 3, gap = 4;
      for (let d = 0; d < len; d += dashLen + gap) {
        const t1 = d / len, t2 = Math.min(1, (d + dashLen) / len);
        const mx = x1 + (x2 - x1) * (t1 + t2) / 2;
        const mz = z1 + (z2 - z1) * (t1 + t2) / 2;
        const segLen = (t2 - t1) * len;
        const geo = new THREE.PlaneGeometry(0.3, segLen);
        geo.rotateX(-Math.PI / 2);
        geo.rotateY(-Math.atan2(dx, dz));
        geo.translate(mx, 0.03, mz);
        dashGeos.push(geo);
      }
    }
  }
  if (dashGeos.length) {
    const dashes = new THREE.Mesh(mergeGeometries(dashGeos), new THREE.MeshBasicMaterial({ color: 0xffffff }));
    group.add(dashes);
    dashGeos.forEach(g => g.dispose());
  }

  // ---- Water (Kaduna River) ----
  if (data.water && data.water.length) {
    const waterGeos = [];
    for (const polygon of data.water) {
      if (polygon.length < 3) continue;
      // Build a simple water mesh from the polygon points
      // Use a triangulated fan from the centroid
      let cx = 0, cz = 0;
      for (const [x, z] of polygon) { cx += x; cz += z; }
      cx /= polygon.length; cz /= polygon.length;
      // Create a flat plane covering the bounding box of the polygon
      let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
      for (const [x, z] of polygon) {
        if (x < minX) minX = x; if (x > maxX) maxX = x;
        if (z < minZ) minZ = z; if (z > maxZ) maxZ = z;
      }
      const w = maxX - minX, d = maxZ - minZ;
      if (w < 1 || d < 1) continue;
      const geo = new THREE.PlaneGeometry(w, d);
      geo.rotateX(-Math.PI / 2);
      geo.translate((minX + maxX) / 2, 0.01, (minZ + maxZ) / 2);
      waterGeos.push(geo);
    }
    if (waterGeos.length) {
      const waterMesh = new THREE.Mesh(
        mergeGeometries(waterGeos),
        new THREE.MeshLambertMaterial({ color: 0x2a6a9a, transparent: true, opacity: 0.85 })
      );
      waterMesh.receiveShadow = true;
      group.add(waterMesh);
      waterGeos.forEach(g => g.dispose());
    }
  }

  // ---- Buildings (Kenney house models on footprints) ----
  // We use simple box geometry for buildings (since we can't async-load GLBs here).
  // The city.js addCity() already places Kenney houses; this adds the building
  // colliders and map shapes so the minimap shows the real layout.
  const buildingGeos = [];
  const palette = [0xf1e6cf, 0xe8d3b0, 0xd9a273, 0xf4f1ea, 0xcfe0c5, 0xe9c9a4, 0xf0d8c8, 0xc7d9e6, 0xe2b98f];
  for (const b of data.buildings) {
    const h = 3 + b.levels * 3;
    const color = palette[(b.x * 7 + b.z * 13) % palette.length];
    const geo = new THREE.BoxGeometry(b.w, h, b.d);
    geo.translate(b.x, h / 2, b.z);
    // Vertex colors
    const c = new THREE.Color(color);
    const col = new Float32Array(geo.attributes.position.count * 3);
    for (let i = 0; i < geo.attributes.position.count; i++) {
      col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
    }
    geo.setAttribute("color", new THREE.BufferAttribute(col, 3));
    buildingGeos.push(geo);
    // Collider (axis-aligned bounding box)
    colliders.push({ minX: b.x - b.w / 2, maxX: b.x + b.w / 2, minZ: b.z - b.d / 2, maxZ: b.z + b.d / 2 });
    mapShapes.buildings.push({ x: b.x, z: b.z, w: b.w, d: b.d });
  }
  if (buildingGeos.length) {
    const buildingsMesh = new THREE.Mesh(
      mergeGeometries(buildingGeos),
      new THREE.MeshLambertMaterial({ vertexColors: true })
    );
    buildingsMesh.castShadow = false; buildingsMesh.receiveShadow = true;
    group.add(buildingsMesh);
    buildingGeos.forEach(g => g.dispose());
  }

  // ---- Landmark markers (entrance pads) ----
  // Place entrance markers at real landmark positions
  if (data.landmarks) {
    for (const lm of data.landmarks) {
      // Small colored pad on the ground
      const pad = new THREE.Mesh(
        new THREE.CircleGeometry(2.5, 20),
        new THREE.MeshBasicMaterial({ color: 0xf2b134, transparent: true, opacity: 0.3 })
      );
      pad.rotation.x = -Math.PI / 2;
      pad.position.set(lm.x, 0.05, lm.z);
      group.add(pad);
      // Ring
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(2.3, 2.5, 20),
        new THREE.MeshBasicMaterial({ color: 0xf2b134, side: THREE.DoubleSide })
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.set(lm.x, 0.06, lm.z);
      group.add(ring);
      mapShapes.buildings.push({ x: lm.x, z: lm.z, w: 4, d: 4, landmark: true, name: lm.name });
    }
  }

  scene.add(group);

  return {
    group,
    colliders,
    mapShapes,
    dispose() {
      scene.remove(group);
      group.traverse(o => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          const mats = Array.isArray(o.material) ? o.material : [o.material];
          mats.forEach(m => m.dispose());
        }
      });
    },
  };
}
